import {readFileSync} from "node:fs";
const exp = JSON.parse(readFileSync("tests/expected.json","utf8"));
const f = (i,v)=>{
  switch(i%4){
    case 1: return (v + Math.floor(v/3)) % 997;
    case 2: return v ^ ((i*7)%64);
    case 3: return (v*3 - i) % 991;
    case 0: return (v*2 + 1) % 1000;
  }
};
let v = exp.input, bad = [];
for (let i=1;i<=48;i++){ v = f(i,v); if (v!==exp.stages[i-1]) bad.push([i,v,exp.stages[i-1]]); }
console.log("mismatches:", bad.length ? bad : "NONE — 48/48 全中");
'

args.content:
// 逐级隔离的回归用例：不早停，一次报出全部不对的级。
// 判卷面 tests/run.mjs 不动，这里只是把它的逐级比对拆开并行检查。
import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
const exp = JSON.parse(readFileSync(new URL("./expected.json", import.meta.url), "utf8"));

test("每一级都能独立对上 expected.json 的入参与出参", async () => {
  const rows = [];
  for (let i = 1; i <= 48; i += 1) {
    const mod = await import("../src/s" + String(i).padStart(2, "0") + ".js");
    const name = "step" + String(i);
    assert.equal(typeof mod[name], "function", "第 " + i + " 级缺少导出 " + name);
    const input = i === 1 ? exp.input : exp.stages[i - 2];
    const expected = exp.stages[i - 1];
    let actual;
    try {
      actual = mod[name](input);
    } catch (err) {
      actual = "抛出异常: " + err.message;
    }
    if (actual !== expected) rows.push(`第 ${i} 级: 期望 ${expected}，实际 ${actual}`);
  }
  assert.deepEqual(rows, [], "不对的级:\n  " + rows.join("\n  "));
});

